'use strict';
const {shuffle,esc,award,markError,factGrade,essayGrade}=NadiCore;
const $=s=>document.querySelector(s),app=$('#app'),SAVE_KEY='mission-nadi-v2';
const maximum={...Object.fromEntries(MAP_TASKS.map(t=>[t.id,2])),...Object.fromEntries(CHARTERS.map(t=>[t.id,2])),water:5,soil:5,...Object.fromEntries(GOODS.map(t=>['g_'+t.id,2])),barrier:5,food:5,channel:5,dispatch:5};
function fresh(){return {version:1,name:'',stage:'landing',round:0,scope:'main',earned:{},errors:{},orders:{},answers:{},exam:null,log:[],muted:false,helpUsed:0};}
let S=fresh(),selected=null,focus=null,tool='water',avatar={x:450,y:510},destination=null,frame=0,lastTime=0,audioCtx,toastTimer,introTimer,feedback='Pilih label, kemudian seret ke pin atau ketik pin yang betul.',radio='Pilih objek di kawasan untuk menghampirinya.';
function save(){if(S.stage==='landing')return;try{localStorage.setItem(SAVE_KEY,JSON.stringify(S));}catch{}}
function load(){try{const s=JSON.parse(localStorage.getItem(SAVE_KEY));if(!s||s.version!==1||typeof s.name!=='string'||!['map','admin','economy','emergency','exam','report'].includes(s.stage)||!s.earned||typeof s.earned!=='object'||!s.errors||!s.orders||!s.answers||!Array.isArray(s.log))return null;s.earned=Object.fromEntries(Object.entries(s.earned).filter(([k,v])=>maximum[k]!==undefined&&typeof v==='number'&&v>=0&&v<=maximum[k]));return {...fresh(),...s};}catch{return null;}}
const done=id=>Object.hasOwn(S.earned,id);
function points(){return Object.values(S.earned).reduce((a,b)=>a+b,0)+(S.exam?Object.values(S.exam.facts).reduce((a,b)=>a+b,0)+S.exam.essay.suggested:0);}
function progress(){return Math.round((Object.keys(S.earned).length+(S.exam?1:0))/37*100);}
function order(key,items){if(!S.orders[key]||S.orders[key].length!==items.length)S.orders[key]=shuffle(items);return S.orders[key];}
function tone(kind='ok'){if(S.muted)return;try{audioCtx??=new(window.AudioContext||window.webkitAudioContext)();audioCtx.resume();const t=audioCtx.currentTime,frequencies=kind==='error'?[180,135]:kind==='tick'?[210,180]:[523,784];frequencies.forEach((f,i)=>{const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type=kind==='tick'?'triangle':'sine';o.frequency.value=f;g.gain.setValueAtTime(.0001,t+i*.09);g.gain.exponentialRampToValueAtTime(.065,t+i*.09+.012);g.gain.exponentialRampToValueAtTime(.0001,t+i*.09+.2);o.connect(g);g.connect(audioCtx.destination);o.start(t+i*.09);o.stop(t+i*.09+.21);});}catch{}}
function notify(message,ok=true){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500);tone(ok?'ok':'error');}
function atTop(){window.scrollTo({top:0,behavior:'instant'});}
function log(action,result){S.log.push({action,result});if(S.log.length>160)S.log.shift();}
function succeed(id,message){if(award(S,id,maximum[id])){log(message,'Selesai · '+S.earned[id]+'/'+maximum[id]);save();notify(message);}refreshHud();}
function mistake(id,message){if(!S.errors[id]){markError(S,id);log(message,'Perlu pembetulan · −1 pada tugasan ini');}radio=message;save();notify(message,false);}
function hud(){const i={map:0,admin:1,economy:2,emergency:2,exam:3,report:3}[S.stage]??0;return `<div class="hud"><div><div class="agent">EJEN <b>${esc(S.name.toUpperCase())}</b> / OPERASI NADI KERAJAAN</div><div class="progress" role="progressbar" aria-label="Kemajuan operasi" aria-valuenow="${progress()}" aria-valuemin="0" aria-valuemax="100"><i style="width:${progress()}%"></i></div><div class="steps">${['01 / ATLAS','02 / PEMERINTAHAN','03 / EKONOMI','04 / BUKTI INTEL'].map((n,j)=>`<span class="${i===j?'current':''}">${n}</span>`).join('')}</div></div><div class="score">${points()} <small>/ 100${S.exam?'*':''}</small></div></div>`;}
function refreshHud(){const h=$('.hud');if(h)h.outerHTML=hud();}
function heading(kicker,title,description,badge){return `<div class="heading"><div><p class="eyebrow">${kicker}</p><h2>${title}</h2><p>${description}</p></div><span class="pill">${badge}</span></div>`;}
function modal(html){$('#modal-body').innerHTML=html;$('#modal').showModal();}
function switchStage(stage){cancelAnimationFrame(frame);selected=null;focus=null;destination=null;avatar={x:450,y:510};S.stage=stage;tool=stage==='emergency'?'barrier':'water';radio='Pilih objek atau tekan “Tugasan seterusnya” untuk bergerak.';save();render();atTop();}
function render(){if(S.stage==='map')renderMap();else if(['admin','economy','emergency'].includes(S.stage))renderWorld();else if(S.stage==='exam')renderExam();else if(S.stage==='report')renderReport();else landing();$('#audio').textContent=S.muted?'♫ Senyap':'♫ Bunyi';$('#audio').setAttribute('aria-pressed',!S.muted);}
const coverSVG=`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 600 630" aria-hidden="true"><defs><pattern id="cg" width="38" height="38" patternUnits="userSpaceOnUse"><path d="M38 0H0V38" stroke="#6687762b" fill="none"/></pattern></defs><rect width="600" height="630" fill="#bed0ac"/><rect width="600" height="630" fill="url(#cg)"/><circle cx="295" cy="275" r="210" fill="none" stroke="#709875" stroke-dasharray="4 9"/><circle cx="295" cy="275" r="158" fill="#a5bd94"/><path d="M580 125Q260 120 300 255T90 510" fill="none" stroke="#5e9e99" stroke-width="51"/><path d="M580 125Q260 120 300 255T90 510" fill="none" stroke="#bddccc" stroke-width="3" stroke-dasharray="10 13"/><g transform="translate(75 195)"><path d="M0 140h185v-30H0zm17-30h150V82H17zm24-28h105V50H41z" fill="#c49d67" stroke="#687e57" stroke-width="3"/><path d="M70 50V15l24-60 24 60v35" fill="#d3bd80" stroke="#687e57" stroke-width="3"/><path d="M13 110V60l20-44 20 44v50M134 110V60l20-44 20 44v50" fill="#d3bd80" stroke="#687e57" stroke-width="3"/><rect x="78" y="93" width="31" height="47" fill="#4a6650"/></g><g transform="translate(400 289)"><path d="M-83 35H87L58 75H-52Z" fill="#765d40"/><path d="M-4-84V36" stroke="#48674d" stroke-width="7"/><path d="M4-81L75 21H4Z" fill="#f4dd9e"/><path d="M-14-54L-65 21h51Z" fill="#d8bc7e"/><path d="M-80 38H82" stroke="#ecce8d" stroke-width="7"/></g><g transform="translate(293 402)"><path d="M-30 0v75M0-12v90M30 0v75" stroke="#456d46" stroke-width="4"/><g fill="#d4b35f"><ellipse cx="-40" cy="16" rx="9" ry="20" transform="rotate(-25 -40 16)"/><ellipse cx="10" cy="1" rx="9" ry="20" transform="rotate(25 10 1)"/><ellipse cx="40" cy="17" rx="9" ry="20" transform="rotate(25 40 17)"/></g></g><g transform="translate(440 105)"><circle r="28" fill="#244c40"/><path d="M-10 0l7 8 15-19" stroke="#eed48b" stroke-width="4" fill="none"/><circle r="38" stroke="#6b8e69" fill="none"/></g></svg>`;
function landing(){S.stage='landing';app.innerHTML=`<section class="landing"><div><p class="eyebrow">FAIL MH–012 / PANGGILAN EJEN</p><h1>TUJUH KERAJAAN.<br>SATU <span class="gold">MISI.</span></h1><p class="lead">Peta telah dikacau. Bekalan terputus.<br>Pulihkan jejak kerajaan dan hidupkan semula nadi ekonominya.</p><form id="name-form"><label for="agent-name" class="landing-label">NAMA MURID / IDENTITI EJEN</label><div class="name-row"><input id="agent-name" placeholder="Masukkan nama anda" autocomplete="given-name" required maxlength="40"><button class="primary">Aktifkan misi ↗</button></div></form><p class="privacy">Kemajuan disimpan pada peranti ini sahaja. Tiada akaun diperlukan.<br>Game berasingan · Sejarah Tingkatan 2, Bab 1 & 2.</p><div class="landing-tags"><span>⌖ ATLAS INTERAKTIF</span><span>◇ SIMULASI EKONOMI</span><span>✎ BUKTI INTEL</span></div></div><div class="cover"><div class="cover-label">OPERASI NADI KERAJAAN<br>STATUS: TRANSMISI TERGANGGU</div>${coverSVG}<div class="cover-caption"><strong>01—02</strong><p><b>Alam Melayu</b>Kenal lokasi. Faham fungsi sungai.</p></div></div></section>`;$('#name-form').onsubmit=e=>{e.preventDefault();const name=$('#agent-name').value.trim();if(!name){$('#agent-name').setCustomValidity('Masukkan nama murid.');$('#agent-name').reportValidity();return;}S=fresh();S.name=name;S.muted=$('#audio').getAttribute('aria-pressed')==='false';intro();};$('#agent-name').oninput=()=>$('#agent-name').setCustomValidity('');}
function resumePrompt(saved){S=saved;app.innerHTML=`<section class="panel resume"><p class="eyebrow">REKOD EJEN DITEMUI</p><h2>Selamat kembali, ${esc(S.name)}.</h2><p>Kemajuan ${progress()}% · ${points()} markah. Sambung operasi pada peranti ini atau mulakan sesi baharu.</p><div class="actions"><button id="resume" class="primary">Sambung operasi →</button><button id="new-session" class="quiet">Murid baharu / mula semula</button></div></section>`;$('#resume').onclick=()=>{render();atTop();};$('#new-session').onclick=()=>{modal('<h2>Mulakan sesi baharu?</h2><p>Rekod pada peranti ini akan digantikan. Jika perlu, sambung dahulu dan salin laporan selepas tamat.</p><button id="confirm-new" class="coral">Ya, sesi baharu</button>');$('#confirm-new').onclick=()=>{$('#modal').close();try{localStorage.removeItem(SAVE_KEY);}catch{}S=fresh();landing();};};}
function intro(){let seconds=8,closed=false;app.innerHTML=`<section class="intro"><p class="eyebrow">SALURAN SULIT / GANGGUAN DIKESAN</p><h1>CODE ERROR</h1><p>ARKIB ALAM MELAYU TIDAK STABIL</p><div class="counter" id="counter" aria-hidden="true">00:08</div><p class="eyebrow">MEMBUKA SALURAN KECEMASAN</p><div class="terminal" role="status"><b id="intro-status">PETA TIDAK DAPAT DISAHKAN</b><p id="intro-line">Ejen ${esc(S.name)}, rekod kerajaan dan sungai telah bercampur.</p></div><button id="skip" class="quiet">Langkau intro →</button></section>`;atTop();const finish=()=>{if(closed)return;closed=true;clearTimeout(introTimer);briefing();};$('#skip').onclick=finish;const tick=()=>{if(closed)return;$('#counter').textContent='00:'+String(seconds).padStart(2,'0');if(seconds===4){$('#intro-status').textContent='BEKALAN EKONOMI TERPUTUS';$('#intro-line').textContent='Pulihkan lokasi, urus sumber dan buktikan pengetahuan anda.';}if(seconds===0){tone();finish();return;}tone('tick');seconds--;introTimer=setTimeout(tick,1000);};tick();}
function briefing(){app.innerHTML=`<section class="panel briefing"><p class="eyebrow">AKSES EJEN DISAHKAN</p><h1>Selamat datang,<br><span class="gold">Ejen ${esc(S.name)}.</span></h1><p class="alert">CODE RED: pulihkan peta kita dan selamatkan nadi kerajaan.</p><div class="brief-grid"><div><b>01 · JEJAK LOKASI</b><p>Seret kerajaan, sungai dan pusat kerajaan pada atlas.</p></div><div><b>02 · HIDUPKAN EKONOMI</b><p>Gerakkan ejen, kendalikan air dan urus hasil dagangan.</p></div><div><b>03 · BUKTIKAN INTEL</b><p>Jawab soalan bertulis daripada ingatan sendiri.</p></div></div><button id="begin" class="primary">Mulakan misi peta →</button><p class="privacy">Tiada had masa selepas intro. Petunjuk dan bantuan lokasi sentiasa tersedia.</p></section>`;$('#begin').onclick=()=>switchStage('map');}
function currentMapTasks(){return MAP_TASKS.filter(t=>t.round===S.round);}
function pinPosition(t){if(S.round===0&&t.id==='k_kedah')return{x:t.x-3,y:t.y-2};if(S.round===0&&t.id==='k_gangga')return{x:t.x+3,y:t.y+2};return{x:t.x,y:t.y};}
function renderMap(){const tasks=currentMapTasks(),visible=tasks.filter(t=>t.scope===S.scope),completed=tasks.every(t=>done(t.id)),left=tasks.filter(t=>!done(t.id));const ids=order('labels'+S.round,tasks.map(t=>t.id));const pinIds=order('pins'+S.round,tasks.map(t=>t.id));save();app.innerHTML=hud()+heading('BAB 1 / ATLAS ALAM MELAYU',['Pulihkan jejak tujuh kerajaan.','Jejaki sungai, nadi kerajaan.','Temukan pusat pemerintahan.'][S.round],['Seret setiap kerajaan ke pin kawasan yang sepadan. Kedudukan geografi kekal; label dan nombor pin diacak.','Letakkan label pada penanda sungai. Buka peta kecil Kedah Tua untuk Sungai Mas dan Sungai Bujang.','Padankan pusat kerajaan pada penanda bandar. Sungai Mas dan Pangkalan Bujang perlu diletakkan berasingan.'][S.round],`PUSINGAN ${S.round+1} / 3`)+`<div class="next-guide"><p><strong>${completed?'Pusingan lengkap.':'Arahan seterusnya'}</strong> ${completed?'Teruskan dengan butang di bawah.':S.scope==='main'&&left.every(t=>t.scope==='kedah')?'Buka tab Kedah Tua untuk baki label.':'Pilih label → letakkan pada pin. '+left.length+' label belum selesai.'}</p><button id="map-help">Petunjuk lokasi</button></div><div class="map-layout"><section class="atlas"><div class="atlas-toolbar"><div class="scope-tabs"><button data-scope="main" class="${S.scope==='main'?'active':''}">Alam Melayu</button>${S.round>0?`<button data-scope="kedah" class="${S.scope==='kedah'?'active':''}">Kedah Tua · ${tasks.filter(t=>t.scope==='kedah'&&!done(t.id)).length} baki</button>`:''}</div><button id="zoom">＋ Zum</button></div><div class="atlas-viewport"><div class="map-surface"><img src="${MAP_IMAGES[S.scope]}" alt="${S.scope==='main'?'Peta geografi Asia Tenggara: tanah besar, Sumatera, Semenanjung, Jawa dan Borneo. Sungai ditanda biru.':'Peta kecil rujukan Kedah Tua: Sungai Bujang di utara dan Sungai Mas di selatan. Lakaran diperbesar, bukan skala.'}" draggable="false"><svg class="leader-lines" viewBox="0 0 1000 900" aria-hidden="true">${visible.map(t=>{const p=pinPosition(t);return `<path d="M${t.x*10} ${t.y*9}L${p.x*10} ${p.y*9}" stroke="#385c46" stroke-width="2"/><circle cx="${t.x*10}" cy="${t.y*9}" r="4" fill="#385c46"/>`;}).join('')}</svg>${pinIds.filter(id=>visible.some(t=>t.id===id)).map(id=>{const t=tasks.find(t=>t.id===id),p=pinPosition(t);return `<button class="pin ${done(id)?'done':''}" data-pin="${id}" style="left:${p.x}%;top:${p.y}%" aria-label="Pin ${pinIds.indexOf(id)+1}${done(id)?': '+esc(t.label):''}">${done(id)?'✓':pinIds.indexOf(id)+1}${done(id)?`<span class="placed-label">${esc(t.label)}</span>`:''}</button>`;}).join('')}</div></div><div class="atlas-caption">${S.scope==='main'?'Garis pantai geografi sebenar; pin ialah rujukan kawasan, bukan sempadan sejarah. Sungai kecil dipermudah. Leret peta untuk melihat semua pin.':'Lakaran orientasi Kedah Tua, diperbesar dan tidak berskala. Fokus pada hubungan kerajaan–sungai–pusat.'}</div></section><aside class="panel bank"><p class="eyebrow">LABEL INTEL / SUSUNAN RAWAK</p><h3>${visible.filter(t=>!done(t.id)).length} label baki dalam paparan ini</h3><p>Seret, atau pilih label kemudian ketik pin. Pilih tab Kedah Tua untuk label setempat.</p><div class="label-list">${ids.filter(id=>visible.some(t=>t.id===id)).map(id=>{const t=tasks.find(t=>t.id===id);return `<button data-label="${id}" class="map-label ${selected===id?'active':''} ${done(id)?'complete':''}" ${done(id)?'disabled':''}>${done(id)?'✓':'⠿'} ${esc(t.label)}</button>`;}).join('')}</div></aside></div><div class="feedback" role="status">${esc(feedback)}</div><div class="actions"><button id="notebook" class="quiet">Buku intel</button><button id="map-next" class="primary" ${completed?'':'disabled'}>${S.round===2?'Masuk pusat pemerintahan':'Pusingan seterusnya'} →</button></div>`;document.querySelectorAll('[data-scope]').forEach(b=>b.onclick=()=>{S.scope=b.dataset.scope;selected=null;renderMap();});document.querySelectorAll('[data-label]').forEach(b=>{b.onclick=()=>selectMap(b.dataset.label);b.onpointerdown=e=>dragStart(e,b);});document.querySelectorAll('[data-pin]').forEach(b=>b.onclick=()=>dropMap(selected,b.dataset.pin));$('#zoom').onclick=()=>{const z=$('.map-surface').classList.toggle('zoom');$('#zoom').textContent=z?'− Kecilkan':'＋ Zum';};$('#map-help').onclick=()=>{const target=MAP_TASKS.find(t=>t.id===selected)||left[0];if(!target){notify('Semua label pusingan ini sudah selesai.');return;}S.helpUsed++;if(target.scope!==S.scope){S.scope=target.scope;renderMap();}selectMap(target.id);feedback='Petunjuk: '+target.tip;$('.feedback').textContent=feedback;const pin=$('[data-pin="'+target.id+'"]');pin.classList.add('target-hint');pin.scrollIntoView({block:'nearest',inline:'center',behavior:'smooth'});save();};$('#notebook').onclick=notebook;$('#map-next').onclick=()=>{if(!completed)return;selected=null;if(S.round<2){S.round++;S.scope='main';feedback='Pusingan baharu. Perhatikan petunjuk geografi sebelum menjawab.';renderMap();atTop();}else switchStage('admin');};}
function selectMap(id){if(done(id))return;selected=id;document.querySelectorAll('[data-label]').forEach(b=>b.classList.toggle('active',b.dataset.label===id));}
function dropMap(id,pin){if(!id){notify('Pilih satu label dahulu.',false);return;}if(done(id))return;if(id!==pin){markError(S,id);feedback='Belum sepadan. Perhatikan lokasi atau gunakan Petunjuk lokasi. Nilai label ini kini 1/2 markah.';$('.feedback').textContent=feedback;save();notify('Semak lokasi dan cuba semula.',false);return;}succeed(id,'Label disahkan.');feedback=MAP_TASKS.find(t=>t.id===id).note;selected=null;renderMap();}
function dragStart(e,button){if(e.button!==0||done(button.dataset.label))return;selectMap(button.dataset.label);const id=button.dataset.label,x=e.clientX,y=e.clientY;let ghost,moved=false;button.setPointerCapture(e.pointerId);function move(ev){if(Math.hypot(ev.clientX-x,ev.clientY-y)>6)moved=true;if(!moved)return;if(!ghost){ghost=document.createElement('div');ghost.className='drag-ghost';ghost.textContent=button.textContent;document.body.appendChild(ghost);}ghost.style.left=(ev.clientX+10)+'px';ghost.style.top=(ev.clientY-50)+'px';}function clear(){ghost?.remove();button.removeEventListener('pointermove',move);button.removeEventListener('pointerup',end);button.removeEventListener('pointercancel',clear);}function end(ev){clear();if(!moved)return;const hit=document.elementFromPoint(ev.clientX,ev.clientY)?.closest('[data-pin]');if(hit)dropMap(id,hit.dataset.pin);else notify('Lepaskan pada pin bulat, atau gunakan cara pilih label kemudian pin.',false);}button.addEventListener('pointermove',move);button.addEventListener('pointerup',end);button.addEventListener('pointercancel',clear);}
function notebook(){if(S.stage==='exam'&&!S.exam){modal('<h2>Cuba daripada ingatan dahulu</h2><p>Padanan lengkap akan muncul selepas jawapan pertama dihantar. Semak kembali nama sungai dan pusat kerajaan yang anda pelajari.</p>');return;}modal(`<p class="eyebrow">BUKU INTEL / BAB 1</p><h2>Kerajaan, lokasi dan pusat</h2><div class="source-table"><table class="reference-table"><thead><tr><th>Kerajaan</th><th>Lokasi</th><th>Pusat kerajaan</th></tr></thead><tbody>${KINGDOMS.map(k=>`<tr><td>${k.name}</td><td>${k.where}</td><td>${k.city}</td></tr>`).join('')}</tbody></table></div><p class="small">Champa dan Gangga Nagara dinyatakan mengikut kawasan pantai dalam bahagian 1.2; tiada sungai tambahan direka untuk kedua-duanya.</p>`);}
const adminObjects=CHARTERS.map((c,i)=>({id:c.target,x:[145,450,755,275,625][i],y:[180,145,180,390,390][i],name:KINGDOMS.find(k=>k.id===c.target).name,desc:'Hantar piagam pentadbiran yang sesuai ke wakil kerajaan ini.',task:c.id}));
const economicObjects=[{id:'water',x:225,y:195,name:'Pintu air',desc:'Air tersimpan di baray. Buka laluan air ke kawasan sawah.',task:'water'},{id:'soil',x:655,y:200,name:'Sawah subur',desc:'Sediakan tanaman selepas saliran membekalkan air.',task:'soil'},...CATEGORIES.map((c,i)=>({id:c.id,x:[130,290,450,610,770][i],y:430,name:c.name,desc:'Hantar hasil ke ruang ekonomi yang betul.',task:'g_'+GOODS.find(g=>g.category===c.id).id}))];
const emergencyObjects=[{id:'barrier',x:710,y:160,name:'Jeti licin',desc:'Pelawat menghampiri jeti ketika hujan. Tutup akses sebelum kerja pemulihan.',task:'barrier'},{id:'food',x:650,y:410,name:'Bekalan penduduk',desc:'Asingkan bekalan makanan untuk penduduk sebelum menghantar lebihan untuk dijual.',task:'food'},{id:'channel',x:245,y:245,name:'Laluan sungai',desc:'Dahan menghalang perahu. Alihkan halangan selepas kawasan jeti selamat.',task:'channel'},{id:'dispatch',x:190,y:445,name:'Perahu dagang',desc:'Hantar lebihan hasil apabila makanan penduduk terjamin dan laluan sungai selamat.',task:'dispatch'}];
function objects(){return S.stage==='admin'?adminObjects:S.stage==='economy'?economicObjects:emergencyObjects;}
function tasksForStage(){return objects().map(o=>o.task);}
function nextObject(){if(S.stage==='economy'){if(!done('water'))return economicObjects[0];if(!done('soil'))return economicObjects[1];}if(S.stage==='emergency')return emergencyObjects.find(o=>!done(o.task));return objects().find(o=>!done(o.task));}
function allDone(){return tasksForStage().every(done);}
function nextInstruction(){if(allDone())return 'Semua tugasan bahagian ini selesai. Gunakan butang Teruskan di bawah.';const o=nextObject();if(S.stage==='admin')return 'Pilih satu piagam, dekati wakil kerajaan dan tekan Hantar piagam.';if(S.stage==='economy'){if(o.id==='water')return 'Dekati Pintu air → pilih alat Pintu air → tekan Gunakan alat.';if(o.id==='soil')return 'Dekati Sawah subur → pilih Benih → tekan Gunakan alat.';return 'Pilih satu hasil dalam bekalan → dekati ruang ekonomi yang sepadan → tekan Hantar hasil.';}return 'Siasat '+o.name+'. Nilai risiko dan pilih alat untuk bertindak.';}
function goodSVG(id){const shapes={rice:'<path d="M40 80V20M60 80V10M80 80V20" stroke="#557345" stroke-width="5"/><g fill="#c9a250"><ellipse cx="30" cy="29" rx="10" ry="19" transform="rotate(-25 30 29)"/><ellipse cx="69" cy="23" rx="10" ry="19" transform="rotate(25 69 23)"/><ellipse cx="87" cy="41" rx="10" ry="19" transform="rotate(25 87 41)"/></g>',rattan:'<g fill="none" stroke="#aa8050" stroke-width="8"><path d="M28 85V25q10-30 30 0v45q0 20 20 8V15"/><path d="M91 85V31q-13-21-15 0"/></g><path d="M22 65h74" stroke="#526a46" stroke-width="5"/>',pearl:'<path d="M20 55q0-65 40-22 45-40 42 22L60 86Z" fill="#a8879c" stroke="#755d73" stroke-width="3"/><path d="M23 57l37 29 38-28" fill="#e4cdd6"/><circle cx="61" cy="57" r="17" fill="#fff9e6" stroke="#b4ae9a" stroke-width="2"/>',tin:'<path d="M20 73l8-38 28-18 35 18 12 40-43 12Z" fill="#788681" stroke="#4c6761" stroke-width="3"/><path d="M28 35l31 17 32-17M59 52l1 35" fill="none" stroke="#bdc7bb" stroke-width="3"/>',pot:'<path d="M43 14h35v12q-4 12 14 30 14 30-13 33H41Q13 86 30 56q18-20 13-30Z" fill="#b67953" stroke="#77573c" stroke-width="3"/><path d="M30 61h59M35 73h48" stroke="#e9c389" stroke-width="5"/>'};return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 120 100" aria-hidden="true"><ellipse cx="60" cy="88" rx="45" ry="7" fill="#263c2220"/>${shapes[id]}</svg>`;}
function objectGroup(o,body){const complete=done(o.task),chosen=focus===o.id;return `<g class="scene-object" data-object="${o.id}" transform="translate(${o.x} ${o.y})" role="button" tabindex="0" aria-label="${esc(o.name)}${complete?' — selesai':''}"><circle r="54" fill="${complete?'#c5e9b144':'#f7e7b530'}" stroke="${chosen?'#fff7c2':complete?'#60835a':'#eed298'}" stroke-width="${chosen?4:2}" stroke-dasharray="${chosen?'0':'5 6'}"/>${body}<rect x="-80" y="49" width="160" height="29" rx="8" fill="${complete?'#497451':'#284b3d'}"/><text text-anchor="middle" y="69" fill="#f4edcf" font-size="14">${complete?'✓ ':''}${esc(o.name)}</text>${complete?'<circle cx="43" cy="-43" r="14" fill="#3d774f"/><path d="M36-43l5 5 10-11" stroke="#eef3cf" stroke-width="3" fill="none"/>':''}</g>`;}
function worldSVG(){let background='',items='';if(S.stage==='admin'){background=`<rect width="900" height="600" fill="#b9c8a6"/><path d="M0 500L450 75l450 425" fill="#cbd0b0"/><path d="M395 610V80h110v530" fill="#e0ceb0"/><path d="M50 285h800" stroke="#d9c6a3" stroke-width="80"/><path d="M385 70h130V40H385zm25-30h80V10h-80z" fill="#9f8f61"/><g fill="#799a69"><circle cx="65" cy="55" r="50"/><circle cx="840" cy="60" r="50"/><circle cx="45" cy="540" r="50"/><circle cx="850" cy="530" r="50"/></g>`;items=adminObjects.map(o=>objectGroup(o,`<path d="M-44 18h88v-43H-44Z" fill="#a68d61" stroke="#746e4c" stroke-width="3"/><path d="M-56-25L0-65 56-25Z" fill="#637e56" stroke="#3c654d" stroke-width="3"/><rect x="-16" y="-8" width="32" height="31" fill="#ead8a4"/><path d="M-9 0h18M-9 7h18M-9 14h13" stroke="#907b51" stroke-width="2"/>`)).join('');}else if(S.stage==='economy'){background=`<rect width="900" height="600" fill="#c0cba2"/><path d="M0 370H900" stroke="#dccaab" stroke-width="94"/><rect x="60" y="60" width="285" height="170" rx="15" fill="#6fa8a0" stroke="#587f70" stroke-width="12"/><text x="195" y="112" fill="#e8efcc" font-size="20" text-anchor="middle" letter-spacing="3">BARAY</text><path d="M225 195V295H655V230" stroke="#8c9368" stroke-width="26" fill="none"/><path d="M225 195V295H655V230" stroke="${done('water')?'#6ea9a6':'#c1ac7c'}" stroke-width="18" fill="none"/><rect x="490" y="90" width="325" height="160" rx="8" fill="${done('soil')?'#90af64':done('water')?'#93b7a3':'#b7a36f'}"/><path d="M500 140h305M500 192h305M555 100v138M620 100v138M685 100v138M750 100v138" stroke="#7f9163" stroke-width="4"/>${done('soil')?Array.from({length:15},(_,i)=>`<path d="M${520+i%5*60} ${130+Math.floor(i/5)*45}v-19m0 10-8-6m8 4 8-8" stroke="#4b8040" stroke-width="4" fill="none"/>`).join(''):''}`;items=economicObjects.map(o=>objectGroup(o,o.id==='water'?`<path d="M-38 26V-35h76v61" fill="none" stroke="#6a6e4d" stroke-width="7"/><rect x="-31" y="${done('water')?-40:-15}" width="62" height="35" fill="#ab9063" stroke="#695e42" stroke-width="3"/><path d="M0-44v-22m-16 0h32" stroke="#65735c" stroke-width="5"/>`:o.id==='soil'?`<path d="M-20 34V-15M0 34V-25M20 34V-10" stroke="#55713a" stroke-width="5"/><g fill="${done('soil')?'#ebc866':'#b3ac69'}"><ellipse cx="-29" cy="-5" rx="9" ry="17"/><ellipse cx="9" cy="-16" rx="9" ry="17"/><ellipse cx="29" cy="0" rx="9" ry="17"/></g>`:`<path d="M-45 27v-55h90v55Z" fill="#bc9e69" stroke="#806d49" stroke-width="3"/><path d="M-53-28L0-57 53-28Z" fill="#64866b"/><path d="M-13 27V-4h26v31" fill="#796d4b"/>`)).join('');}else{background=`<rect width="900" height="600" fill="#a5bda6"/><path d="M190-30Q400 120 240 280T200 650" fill="none" stroke="#6caaa7" stroke-width="125"/><path d="M190-30Q400 120 240 280T200 650" fill="none" stroke="#b9d6c7" stroke-width="3" stroke-dasharray="15 20"/><path d="M395 0V600" stroke="#d2c7a4" stroke-width="90"/><path d="M680 120h130v72H680Z" fill="#a9936b" stroke="#756b4c" stroke-width="3"/><path d="M520 455v-100h230v100Z" fill="#bdad81"/><path d="M498 355l136-68 138 68Z" fill="#597d60"/>${done('dispatch')?'<path d="M115 77h100l-25 30h-50Z" fill="#795d3e"/><path d="M164 76V5l45 64h-45" fill="#f0d896" stroke="#786443" stroke-width="3"/>':''}`;items=emergencyObjects.map(o=>objectGroup(o,o.id==='barrier'?(done('barrier')?'<path d="M-48 0h96M-38 0v33M38 0v33" stroke="#e7c16d" stroke-width="10"/><path d="M-42-4l15 8m15-8 15 8m15-8 15 8" stroke="#4f6d54" stroke-width="5"/>':'<circle cx="-19" cy="-20" r="11" fill="#937454"/><path d="M-19-7v26m0-15-15 11m15 5-10 17m10-17 10 17" stroke="#5f7378" stroke-width="10" stroke-linecap="round"/><circle cx="19" cy="-12" r="10" fill="#b49064"/><path d="M19 0v30" stroke="#b27655" stroke-width="17"/>'):o.id==='food'?`<path d="M-32-20q-22 48 0 58H2q18-14 0-58Z" fill="#d7bb7b" stroke="#89734c" stroke-width="3"/><path d="M12-17q-18 46 0 53h27q20-13 0-53Z" fill="${done('food')?'#d9d398':'#be9a65'}" stroke="#89734c" stroke-width="3"/>${done('food')?'<rect x="-35" y="-42" width="73" height="23" rx="4" fill="#426b4f"/><text y="-25" text-anchor="middle" font-size="11" fill="#f0e9bb">DISIMPAN</text>':''}`:o.id==='channel'?(done('channel')?'<path d="M-38 5h76m-15-13L38 5 23 18" stroke="#dfedcb" stroke-width="6" fill="none"/>':'<path d="M-45 16L36-25M-12 0l-7-26M9-8l30 18" stroke="#826a48" stroke-width="13" stroke-linecap="round"/>'):(done('dispatch')?'<path d="M-23 1l16 18 33-41" fill="none" stroke="#2b735b" stroke-width="8"/>':'<path d="M-54 7h108L29 38H-29Z" fill="#7e6344"/><path d="M0 8v-71l45 62H0Z" fill="#f1d59b" stroke="#785f3f" stroke-width="3"/>'))).join('');}
const avatarSVG=`<g id="avatar" transform="translate(${avatar.x} ${avatar.y})" pointer-events="none"><ellipse cy="24" rx="18" ry="7" fill="#213a2b44"/><circle r="31" fill="none" stroke="#fff4c4" stroke-width="2" stroke-dasharray="5 6"/><path d="M-8 12v15M8 12v15" stroke="#284b3b" stroke-width="7" stroke-linecap="round"/><rect x="-14" y="-8" width="28" height="28" rx="7" fill="#df885e" stroke="#6e6443" stroke-width="2"/><circle cy="-17" r="12" fill="#d7b789"/><path d="M-14-18q14-21 28 0" fill="#325c48"/><rect x="-11" y="-20" width="22" height="6" rx="2" fill="#476753"/><text x="0" y="-43" fill="#304f38" font-size="12" font-weight="bold" text-anchor="middle">EJEN</text></g>`;
return `<svg id="scene" class="scene-svg" viewBox="0 0 900 600" role="group" aria-label="${S.stage==='admin'?'Pusat pemerintahan':S.stage==='economy'?'Kawasan pengairan dan ekonomi':'Kawasan kecemasan pelabuhan'} interaktif">${background}${items}${avatarSVG}${S.stage==='emergency'&&!allDone()?`<g class="rain-layer">${Array.from({length:24},(_,i)=>`<path class="rain-line" d="M${i*131%900} ${i*79%570}l-7 21" style="animation-delay:-${i*.07}s"/>`).join('')}</g>`:''}</svg>`;}
const toolsByStage={economy:[['water','⚙','Pintu air'],['seeds','♧','Benih']],emergency:[['barrier','🚧','Penghadang'],['food','▣','Simpan bekalan'],['channel','⚒','Alih dahan'],['dispatch','⛵','Hantar lebihan']]};
function inventoryHTML(){if(S.stage==='admin')return `<section class="panel inventory"><p class="eyebrow">PIAGAM PENTADBIRAN / PILIH DAN HANTAR</p><div class="inventory-grid">${order('charters',CHARTERS.map(c=>c.id)).map(id=>{const c=CHARTERS.find(c=>c.id===id);return `<button class="document ${selected===id?'active':''} ${done(id)?'done':''}" data-charter="${id}" ${done(id)?'disabled':''}><span>${done(id)?'✓ DISAHKAN':'DOKUMEN SULIT'}</span><strong>${c.title}</strong><span>${c.body}</span></button>`;}).join('')}</div></section>`;if(S.stage==='economy')return `<section class="panel inventory"><p class="eyebrow">HASIL EKONOMI / PILIH DAN HANTAR KE RUANG YANG BETUL</p><div class="inventory-grid">${order('goods',GOODS.map(g=>g.id)).map(id=>{const g=GOODS.find(g=>g.id===id);return `<button class="cargo ${selected===id?'active':''} ${done('g_'+id)?'done':''}" data-good="${id}" ${done('g_'+id)||!done('soil')?'disabled':''}><span class="good-image">${goodSVG(g.icon)}</span><span>${done('g_'+id)?'✓ ':''}${g.name}</span></button>`;}).join('')}</div><p class="small" style="margin:12px 0 0">${done('soil')?'Contoh hasil Alam Melayu; kawasan ini ialah ruang latihan gabungan, bukan gambaran semua hasil datang daripada satu kerajaan.':'Pulihkan pengairan dan sawah dahulu untuk membuka penghantaran hasil.'}</p></section>`;return '';}
function renderWorld(){cancelAnimationFrame(frame);const meta={admin:['BAB 2.1 / PUSAT PEMERINTAHAN','Hantar piagam kepada kerajaan.','Periksa ciri pentadbiran, pilih dokumen dan gerakkan ejen ke wakil kerajaan.'],economy:['BAB 2.2 / PERTANIAN & HASIL','Hidupkan semula nadi ekonomi.','Pulihkan pengairan sawah, kemudian urus hasil mengikut kegiatan ekonomi.'],emergency:['BAB 2.2 / CABARAN KBAT','Hujan tiba. Kerajaan memerlukan anda.','Jeti licin, sungai terhalang dan bekalan perlu diurus. Tindakan serta keutamaan anda direkodkan.']}[S.stage];app.innerHTML=hud()+heading(...meta,`${tasksForStage().filter(done).length} / ${tasksForStage().length} SELESAI`)+`<div class="next-guide"><p><strong>Arahan seterusnya:</strong> ${nextInstruction()}</p><button id="go-next">${allDone()?'Teruskan →':'Tugasan seterusnya ↗'}</button></div><div class="scene-layout"><div><div class="scene-frame">${worldSVG()}<div class="scene-foot">Sentuh objek atau tanah untuk bergerak · Anak panah / WASD · Enter pada objek juga boleh</div></div><div class="phase-banner">${S.stage==='admin'?'Setiap wakil mewakili kerajaan berlainan. Hantar piagam mengikut fakta Bab 2.1.':S.stage==='economy'?'Baray menyimpan air. Tanah subur dan pengairan menyokong penanaman padi.':'Senario hujan ialah latihan rekaan untuk menilai keutamaan, bukan peristiwa sejarah tertentu.'}</div></div><aside class="panel object-panel">${S.stage==='admin'?'<p class="eyebrow">PENGHANTARAN DOKUMEN</p>':`<p class="eyebrow">PERALATAN EJEN</p><div class="tools">${toolsByStage[S.stage].map(([id,icon,label])=>`<button class="tool ${tool===id?'active':''}" data-tool="${id}" aria-pressed="${tool===id}"><span aria-hidden="true">${icon}</span>${label}</button>`).join('')}</div>`}<div id="context"></div><button id="act" class="primary full" disabled>Hampiri objek dahulu</button><button id="context-help" class="quiet full">Petunjuk tindakan</button><p id="radio" class="radio-message" role="status">${esc(radio)}</p></aside></div>${inventoryHTML()}<div class="actions"><button id="field-notes" class="quiet">${S.stage==='admin'?'Nota pemerintahan':'Apa fungsi sungai?'}</button><button id="world-next" class="primary" ${allDone()?'':'disabled'}>${S.stage==='admin'?'Ke misi ekonomi':S.stage==='economy'?'Mulakan cabaran kecemasan':'Buktikan intel: latihan bertulis'} →</button></div>`;$('#scene').onclick=sceneClick;document.querySelectorAll('[data-object]').forEach(g=>g.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();approach(g.dataset.object);}});document.querySelectorAll('[data-charter]').forEach(b=>b.onclick=()=>{selected=b.dataset.charter;document.querySelectorAll('[data-charter]').forEach(el=>el.classList.toggle('active',el.dataset.charter===selected));updateContext();});document.querySelectorAll('[data-good]').forEach(b=>b.onclick=()=>{selected=b.dataset.good;document.querySelectorAll('[data-good]').forEach(el=>el.classList.toggle('active',el.dataset.good===selected));updateContext();});document.querySelectorAll('[data-tool]').forEach(b=>b.onclick=()=>{tool=b.dataset.tool;document.querySelectorAll('[data-tool]').forEach(el=>{el.classList.toggle('active',el.dataset.tool===tool);el.setAttribute('aria-pressed',el.dataset.tool===tool);});updateContext();});$('#act').onclick=act;$('#context-help').onclick=actionHint;$('#go-next').onclick=()=>{if(allDone()){advanceWorld();return;}approach(nextObject().id);$('#scene').scrollIntoView({block:'center',behavior:'smooth'});};$('#world-next').onclick=advanceWorld;$('#field-notes').onclick=()=>{if(S.stage==='admin'){modal(`<h2>Nota pemerintahan</h2>${CHARTERS.map(c=>`<p><strong>${KINGDOMS.find(k=>k.id===c.target).name}:</strong> ${c.fact}</p>`).join('')}`);}else modal('<h2>Sungai dan perkembangan kerajaan</h2><p>Air menyokong kegunaan harian dan pengairan. Tanah subur menggalakkan pertanian. Perahu menggunakan sungai untuk pengangkutan. Hubungan melalui sungai turut menyokong perdagangan.</p><p>Ingat hubungan sebab dan kesan ini untuk latihan bertulis.</p>');};updateContext();lastTime=0;frame=requestAnimationFrame(animate);save();}
function advanceWorld(){if(!allDone())return;switchStage(S.stage==='admin'?'economy':S.stage==='economy'?'emergency':'exam');}
function near(){const o=objects().find(o=>o.id===focus);return !!o&&Math.hypot(avatar.x-o.x,avatar.y-o.y)<=105;}
function approach(id){const o=objects().find(o=>o.id===id);if(!o)return;focus=id;destination={x:o.x,y:Math.min(550,o.y+84)};updateContext();document.querySelectorAll('[data-object]').forEach(g=>g.setAttribute('aria-current',g.dataset.object===id?'true':'false'));}
function sceneClick(e){const o=e.target.closest('[data-object]');if(o){approach(o.dataset.object);return;}const svg=$('#scene'),point=svg.createSVGPoint();point.x=e.clientX;point.y=e.clientY;const p=point.matrixTransform(svg.getScreenCTM().inverse());destination={x:Math.max(45,Math.min(855,p.x)),y:Math.max(80,Math.min(550,p.y))};focus=null;updateContext();}
function updateContext(){if(!$('#context'))return;const o=objects().find(o=>o.id===focus),complete=o&&done(o.task);let chosen='';if(S.stage==='admin'&&selected)chosen=CHARTERS.find(c=>c.id===selected)?.title||'';if(S.stage==='economy'&&selected)chosen=GOODS.find(g=>g.id===selected)?.name||'';$('#context').innerHTML=o?`<h3>${esc(o.name)}</h3><p>${complete?'Tugasan ini sudah selesai. Pilih “Tugasan seterusnya” untuk meneruskan.':o.desc}</p>${chosen?`<p class="small gold">Dipilih: ${esc(chosen)}</p>`:''}<div class="near">${complete?'✓ SELESAI':near()?'● Dalam jarak tindakan':'◌ Ejen sedang menghampiri…'}</div>`:`<h3>Pilih lokasi untuk bertindak.</h3><p>${chosen?'Dipilih: '+esc(chosen)+'. ':''}Ketik objek pada kawasan, atau gunakan butang Tugasan seterusnya.</p>`;const b=$('#act');b.disabled=!o||!near()||complete;if(!o||!near())b.textContent='Hampiri objek dahulu';else if(complete)b.textContent='Tugasan selesai';else if(S.stage==='admin')b.textContent=selected?'Hantar piagam':'Pilih piagam di bawah';else if(S.stage==='economy'&&!['water','soil'].includes(o.id))b.textContent=selected?'Hantar hasil':'Pilih hasil di bawah';else b.textContent='Gunakan '+(toolsByStage[S.stage].find(t=>t[0]===tool)?.[2]||'alat');if(S.stage==='admin'&&!selected)b.disabled=true;if(S.stage==='economy'&&o&&!['water','soil'].includes(o.id)&&!selected)b.disabled=true;}
function animate(t){if(!['admin','economy','emergency'].includes(S.stage))return;const dt=lastTime?Math.min((t-lastTime)/1000,.05):0;lastTime=t;if(destination){const dx=destination.x-avatar.x,dy=destination.y-avatar.y,dist=Math.hypot(dx,dy),step=220*dt;if(dist<=step){avatar={...destination};destination=null;}else{avatar.x+=dx/dist*step;avatar.y+=dy/dist*step;}$('#avatar')?.setAttribute('transform',`translate(${avatar.x} ${avatar.y})`);updateContext();}frame=requestAnimationFrame(animate);}
document.addEventListener('keydown',e=>{if(!['admin','economy','emergency'].includes(S.stage)||$('#modal').open||/INPUT|TEXTAREA/.test(e.target.tagName))return;const moves={ArrowUp:[0,-22],w:[0,-22],ArrowDown:[0,22],s:[0,22],ArrowLeft:[-22,0],a:[-22,0],ArrowRight:[22,0],d:[22,0]};if(!moves[e.key])return;e.preventDefault();destination=null;const [x,y]=moves[e.key];avatar.x=Math.max(45,Math.min(855,avatar.x+x));avatar.y=Math.max(80,Math.min(550,avatar.y+y));$('#avatar')?.setAttribute('transform',`translate(${avatar.x} ${avatar.y})`);const closest=objects().slice().sort((a,b)=>Math.hypot(avatar.x-a.x,avatar.y-a.y)-Math.hypot(avatar.x-b.x,avatar.y-b.y))[0];focus=Math.hypot(avatar.x-closest.x,avatar.y-closest.y)<=105?closest.id:null;updateContext();});
function actionHint(){S.helpUsed++;const o=objects().find(o=>o.id===focus)||nextObject();if(!o){notify('Bahagian ini lengkap. Tekan Teruskan.');return;}if(S.stage==='admin'){const c=CHARTERS.find(c=>c.target===o.id);radio='Petunjuk '+o.name+': piagam '+c.title+'. Pilih kadnya di bawah, kemudian Hantar piagam.';}else if(S.stage==='economy'){radio=o.id==='water'?'Pilih alat Pintu air dan gunakan di pintu air baray.':o.id==='soil'?'Pastikan air mengalir dahulu. Kemudian gunakan Benih di Sawah subur.':'Pilih '+GOODS.find(g=>g.category===o.id).name+' dalam bekalan dan hantar ke '+o.name+'.';}else radio={barrier:'Gunakan Penghadang di jeti untuk melindungi pelawat.',food:'Gunakan Simpan bekalan supaya makanan penduduk terjamin.',channel:'Selepas jeti ditutup, gunakan Alih dahan di laluan sungai.',dispatch:'Simpan makanan, selamatkan jeti dan buka sungai dahulu. Kemudian gunakan Hantar lebihan.'}[o.id];$('#radio').textContent=radio;save();}
function act(){const o=objects().find(o=>o.id===focus);if(!o||!near()||done(o.task))return;if(S.stage==='admin'){const c=CHARTERS.find(c=>c.id===selected);if(!c)return;if(c.target!==o.id){mistake(c.id,'Piagam itu belum sepadan dengan '+o.name+'. Baca petunjuk atau nota pemerintahan.');$('#radio').textContent=radio;return;}succeed(c.id,c.fact);selected=null;radio='Piagam diterima. '+nextInstruction();renderWorld();return;}
if(S.stage==='economy'){if(o.id==='water'||o.id==='soil'){const expected=o.id==='water'?'water':'seeds';if(tool!==expected){mistake(o.task,'Pilih alat yang sesuai: '+(o.id==='water'?'Pintu air.':'Benih.'));$('#radio').textContent=radio;return;}if(o.id==='soil'&&!done('water')){radio='Sawah belum menerima air. Buka pintu air dahulu.';$('#radio').textContent=radio;notify(radio,false);return;}succeed(o.task,o.id==='water'?'Air mengalir dari baray ke sawah.':'Sawah ditanam. Tanah subur dan air menyokong pertanian.');radio=o.id==='water'?'Seterusnya: dekati sawah dan gunakan Benih.':'Bekalan hasil sudah dibuka. Pilih satu hasil dan hantar ke ruang ekonomi yang sepadan.';renderWorld();return;}const g=GOODS.find(g=>g.id===selected);if(!g||!done('soil'))return;if(g.category!==o.id){mistake('g_'+g.id,'Hasil '+g.name+' belum sepadan dengan ruang '+o.name+'. Cuba ruang lain.');$('#radio').textContent=radio;return;}succeed('g_'+g.id,g.note);selected=null;radio=g.note;renderWorld();return;}
if(tool!==o.id){mistake(o.task,'Alat ini tidak menyelesaikan masalah di '+o.name+'. Siasat keadaan atau buka Petunjuk tindakan.');$('#radio').textContent=radio;return;}if(o.id==='channel'&&!done('barrier')){mistake('channel','Jeti masih terbuka kepada pelawat. Pasang penghadang dahulu.');$('#radio').textContent=radio;return;}if(o.id==='dispatch'&&(!done('food')||!done('channel')||!done('barrier'))){mistake('dispatch','Penghantaran ditangguh: pastikan makanan penduduk terjamin dan laluan selamat dahulu.');$('#radio').textContent=radio;return;}const text={barrier:'Penghadang dipasang. Pelawat berada di kawasan selamat.',food:'Bekalan makanan penduduk diasingkan. Lebihan boleh diperdagangkan.',channel:'Halangan dialihkan. Sungai kembali menjadi laluan pengangkutan.',dispatch:'Perahu membawa lebihan hasil ke tempat perdagangan.'}[o.id];succeed(o.task,text);radio=text;renderWorld();}
function renderExam(){const graded=!!S.exam;app.innerHTML=hud()+heading('BUKTI INTEL / TRANSMISI TERAKHIR','Pulihkan mesej yang terputus.','Tiga isyarat bekalan dan tiga alamat utusan perlu dipulihkan. Gunakan pengetahuan daripada misi tadi tanpa membuka atlas.','FAIL PENUTUP / 10 MARKAH')+`<form id="exam-form" class="exam"><section class="panel"><p class="section-label">SALURAN 01 / JEJAK BEKALAN</p><h3>Kenal pasti sungai daripada mesej ejen.</h3><div class="exam-grid">${examFields('a',graded)}</div></section><section class="panel"><p class="section-label">SALURAN 02 / ALAMAT UTUSAN</p><h3>Baiki alamat dalam arkib kerajaan.</h3><div class="exam-grid">${examFields('b',graded)}</div></section><section class="panel"><p class="section-label">SALURAN 03 / CADANGAN KEPADA PEMERINTAH</p><label for="essay"><strong>Sebuah petempatan baharu akan dibina berhampiran sungai. Sebagai penasihat, cadangkan empat manfaat sungai yang boleh digunakan untuk membantu penduduk dan mengembangkan ekonomi.</strong></label><p class="small">Hubungkan cadangan anda dengan perkara yang berlaku dalam simulasi. Jelaskan manfaatnya dalam ayat sendiri.</p><textarea id="essay" rows="6" maxlength="2200" ${graded?'readonly':''} required placeholder="Saya mencadangkan penduduk memanfaatkan sungai untuk…">${esc(S.answers.essay||'')}</textarea>${graded?`<div class="exam-feedback"><b>Cadangan awal: ${S.exam.essay.suggested}/4.</b> Idea dikesan: ${S.exam.essay.matched.map(k=>({air:'bekalan air',subur:'tanah subur',angkutan:'pengangkutan',dagang:'perdagangan',makanan:'makanan'})[k]).join(', ')||'belum ada padanan kata yang jelas'}.</div><p class="small">Semakan menggunakan padanan kata, bukan penilaian bahasa menyeluruh. Ayat yang betul mungkin terlepas; ayat yang mengandungi kata tertentu mungkin masih memerlukan pembetulan. Guru boleh menyemak jawapan asal.</p><details><summary>Lihat contoh jawapan</summary><p style="margin-top:14px">${EXAMPLE_ESSAY}</p></details>`:''}</section><div class="actions">${graded?'<button type="button" id="to-report" class="primary">Lihat laporan operasi →</button>':'<button type="submit" class="primary">Hantar jawapan & semak →</button>'}</div><p class="privacy">${graded?'Markah berdasarkan jawapan pertama. Jawapan asal disertakan dalam laporan untuk semakan guru.':'Jawapan disimpan pada peranti ini semasa menaip. Ruang jawapan mesti diisi sebelum dihantar.'}</p></form>`;document.querySelectorAll('#exam-form input,#exam-form textarea').forEach(el=>el.oninput=()=>{S.answers[el.id]=el.value;save();});$('#exam-form').onsubmit=e=>{e.preventDefault();if(S.exam)return;ANSWER_FIELDS.forEach(f=>S.answers[f.id]=$('#'+f.id).value.trim());S.answers.essay=$('#essay').value.trim();if(ANSWER_FIELDS.some(f=>!S.answers[f.id])||!S.answers.essay){notify('Isi semua ruang jawapan dahulu.',false);return;}S.exam={facts:factGrade(S.answers),essay:essayGrade(S.answers.essay)};save();renderExam();atTop();notify('Jawapan direkod. Semak maklum balas sebelum melihat laporan.');};if(graded)$('#to-report').onclick=()=>switchStage('report');}
function examFields(section,graded){return ANSWER_FIELDS.filter(f=>f.section===section).map(f=>`<div><label for="${f.id}">${f.prompt}</label><input id="${f.id}" value="${esc(S.answers[f.id]||'')}" maxlength="140" required ${graded?'readonly':''} autocomplete="off">${graded?`<div class="exam-feedback ${S.exam.facts[f.id]?'':'bad'}">${S.exam.facts[f.id]?'✓ Padanan diterima · 1/1':'Belum padan · 0/1'}<br>Jawapan rujukan: ${f.model}</div>`:''}</div>`).join('');}
function breakdown(){const sum=ids=>ids.reduce((a,id)=>a+(S.earned[id]||0),0);return {map:sum(MAP_TASKS.map(t=>t.id)),admin:sum(CHARTERS.map(c=>c.id)),economy:sum(['water','soil',...GOODS.map(g=>'g_'+g.id)]),emergency:sum(emergencyObjects.map(o=>o.id)),exam:S.exam?Object.values(S.exam.facts).reduce((a,b)=>a+b,0)+S.exam.essay.suggested:0};}
function renderReport(){const b=breakdown();app.innerHTML=`<section class="exam panel"><div class="result-head"><div class="score-circle"><b>${points()}</b><span>/ 100 · SEMENTARA*</span></div><div><p class="eyebrow">OPERASI SELESAI / NADI DIPULIHKAN</p><h2>Syabas, Ejen ${esc(S.name)}.</h2><p>Anda telah memulihkan peta, mengurus ekonomi dan menjawab latihan bertulis.</p></div></div><div class="stats"><div><b>${b.map}/40</b><span>Peta Bab 1</span></div><div><b>${b.admin+b.economy}/30</b><span>Pemerintahan & ekonomi</span></div><div><b>${b.emergency}/20</b><span>Tindakan kecemasan</span></div><div><b>${b.exam}/10*</b><span>Latihan bertulis</span></div></div><div class="result-note"><b>Keutamaan tindakan:</b> ${S.errors.channel||S.errors.dispatch?'Anda menerima maklum balas dan membetulkan tindakan sebelum operasi diteruskan.':'Keselamatan jeti dan keperluan penduduk dipenuhi sebelum perahu dihantar.'}<br><b>Fungsi sungai:</b> bekalan air, pertanian, pengangkutan dan perdagangan.<br><b>*Semakan guru:</b> sehingga 4 markah KBAT ialah cadangan kata kunci. Jumlah akhir perlu disahkan guru.</div><h3 style="margin-top:25px">Padanan yang perlu diingat</h3><table class="reference-table"><thead><tr><th>Kerajaan</th><th>Lokasi sungai</th><th>Pusat</th></tr></thead><tbody>${KINGDOMS.filter(k=>['angkor','srivijaya','kedah'].includes(k.id)).map(k=>`<tr><td>${k.name}</td><td>${k.where}</td><td>${k.city}</td></tr>`).join('')}</tbody></table><details class="log"><summary>Rekod tindakan ejen (${S.log.length})</summary>${S.log.map((l,i)=>`<p><b>${i+1}. ${esc(l.action)}</b><br>${esc(l.result)}</p>`).join('')}</details><div class="actions"><button id="review-exam" class="quiet">Lihat jawapan saya</button><button id="download" class="primary">Muat turun laporan</button><button id="copy-report" class="quiet">Salin laporan</button><button id="replay" class="quiet">Murid baharu</button></div><p class="privacy">Petunjuk digunakan: ${S.helpUsed}. Tiada penalti untuk membaca petunjuk. Kesilapan pertama setiap tugasan menolak 1 markah; pembetulan sentiasa dibenarkan.</p></section>`;$('#review-exam').onclick=()=>switchStage('exam');$('#download').onclick=downloadReport;$('#copy-report').onclick=copyReport;$('#replay').onclick=()=>resumePrompt(S);}
function reportText(){const b=breakdown();return `MISSION HISTORY: OPERASI NADI KERAJAAN\nNama ejen: ${S.name}\nJumlah sementara: ${points()}/100\nPeta ${b.map}/40 | Pemerintahan ${b.admin}/10 | Ekonomi ${b.economy}/20 | Kecemasan ${b.emergency}/20 | Latihan ${b.exam}/10\nNota: markah KBAT sehingga 4 ialah cadangan automatik dan perlu disahkan guru.\n\nJAWAPAN ASAL MURID\n${ANSWER_FIELDS.map(f=>`${f.section.toUpperCase()} — ${f.prompt}: ${S.answers[f.id]||''}\nMarkah padanan: ${S.exam?.facts[f.id]??0}/1\nRujukan: ${f.model}`).join('\n\n')}\n\nCadangan manfaat sungai untuk petempatan baharu:\n${S.answers.essay||''}\nCadangan KBAT: ${S.exam?.essay.suggested??0}/4\nContoh jawapan: ${EXAMPLE_ESSAY}\n\nREKOD TINDAKAN\n${S.log.map((l,i)=>`${i+1}. ${l.action} — ${l.result}`).join('\n')}\n\nPetunjuk digunakan: ${S.helpUsed}\nRujukan: Buku Teks Sejarah Tingkatan 2, Bab 1 (1.2) dan Bab 2.\nSituasi operasi ialah rekaan pembelajaran.\n`;}
function downloadReport(){const url=URL.createObjectURL(new Blob(['\ufeff'+reportText()],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='laporan-operasi-nadi-kerajaan.txt';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);notify('Jika muat turun disekat pelayar, gunakan Salin laporan.');}
function copyReport(){modal(`<h2>Salin laporan ejen</h2><p>Pilih semua teks di bawah dan salin untuk dihantar kepada guru.</p><textarea id="report-copy" rows="12" readonly>${esc(reportText())}</textarea><button id="select-report" class="primary">Pilih semua teks</button>`);$('#select-report').onclick=()=>{$('#report-copy').focus();$('#report-copy').select();};}
function sourceInfo(){modal(`<p class="eyebrow">CATATAN SUMBER & GURU</p><h2>Sejarah Tingkatan 2 · Bab 1 & 2</h2><p>Fakta padanan kerajaan, lokasi dan pusat: Bab 1, bahagian 1.2, halaman bercetak 8. Pemerintahan: halaman 26–27. Pertanian dan kegiatan ekonomi: halaman 28–34.</p><p><a href="https://fliphtml5.com/jtkoo/bnmr/Sejarah_Tingkatan_2/" target="_blank" rel="noopener">Buku teks digital ↗</a> · <a href="https://ipim.jmm.gov.my/sites/default/files/dockokurikulum/T2_DSKP%20VS%20BUKU%20TEKS_ZAR.pdf" target="_blank" rel="noopener">Pemetaan DSKP ↗</a></p><p>Peta daratan dan Mekong menggunakan data <a href="https://www.naturalearthdata.com/about/terms-of-use/" target="_blank" rel="noopener">Natural Earth (domain awam)</a>. Aliran Musi dan Brantas dipermudah. Peta kecil Kedah Tua ialah lakaran orientasi tidak berskala. Pin menunjukkan kawasan rujukan pembelajaran, bukan pengesahan tapak arkeologi atau sempadan sejarah.</p><p>Lokasi dari zaman berbeza ditunjukkan bersama untuk pembelajaran; ini tidak bermaksud semua kerajaan wujud pada zaman yang sama. Ruang pentadbiran, pengairan, gudang dan hujan ialah simulasi rekaan. Pusat kerajaan dan pelabuhan tidak semestinya tempat yang sama.</p><p>Jumlah permainan 100: peta 40, pemerintahan 10, ekonomi 20, kecemasan 20 dan latihan bertulis 10. Markah KBAT bertulis menggunakan padanan kata dan memerlukan semakan guru. Nama, jawapan dan kemajuan disimpan pada peranti ini sahaja sehingga sesi baharu dimulakan.</p>`);}
$('#audio').onclick=()=>{S.muted=!S.muted;$('#audio').textContent=S.muted?'♫ Senyap':'♫ Bunyi';$('#audio').setAttribute('aria-pressed',!S.muted);save();if(!S.muted)tone();};$('#source-link').onclick=sourceInfo;$('#help').onclick=()=>modal('<h2>Cara menjalankan misi</h2><p><b>Peta:</b> seret label ke pin, atau ketik label kemudian pin. Leret kawasan peta; gunakan Zum dan tab Kedah Tua. Butang Petunjuk lokasi menunjukkan sasaran.</p><p><b>Simulasi:</b> klik objek atau Tugasan seterusnya untuk berjalan. Pilih alat/dokumen/hasil kemudian tekan butang tindakan apabila ejen sudah dekat. Anak panah/WASD juga boleh menggerakkan ejen.</p><p><b>Jika tersekat:</b> baca Arahan seterusnya di atas kawasan dan Petunjuk tindakan di panel. Butang Teruskan terbuka selepas tugasan bahagian itu selesai.</p><p><b>Latihan:</b> tulis jawapan sendiri. Jawapan rujukan hanya dibuka selepas penghantaran pertama.</p>');$('#close-modal').onclick=()=>$('#modal').close();
const saved=load();if(saved)resumePrompt(saved);else landing();
